static void polynomialPreview(char*out,size_t size){size_t used=0;int terms=0;out[0]=0;for(int i=0;i<=polyDegree;i++){const char*s=solverFields[0][i];double v=0;int good=scalar(s,&v);if(good&&v==0)continue;char coefficient[128],term[160],power[24];int p=polyDegree-i;char*end;double literal=strtod(s,&end);int simple=good&&end!=s&&!*end&&isfinite(literal);if(simple){if(p&&fabs(v)==1)coefficient[0]=0;else{const char*mag=s;while(isspace((unsigned char)*mag))mag++;if(*mag=='-'||*mag=='+')mag++;if(strlen(mag)<32)snprintf(coefficient,sizeof(coefficient),"%s",mag);else snprintf(coefficient,sizeof(coefficient),"%.17g",fabs(v));}}else if(good&&strlen(s)<24)snprintf(coefficient,sizeof(coefficient),"(%s)",s);else if(good)snprintf(coefficient,sizeof(coefficient),"(%.12g)",v);else strcpy(coefficient,"(?)");if(p==0)power[0]=0;else if(p==1)strcpy(power,"X");else snprintf(power,sizeof(power),"X^%d",p);const char*sign=simple?(v<0?" - ":terms?" + ":""):terms?" + ":"";snprintf(term,sizeof(term),"%s%s%s%s",sign,coefficient,coefficient[0]&&p?"*":"",power);int n=snprintf(out+used,size-used,"%s",term);if(n<0||(size_t)n>=size-used)break;used+=n;terms++;}if(!terms)snprintf(out,size,"0");}
static long long gcdDisplay(long long a,long long b){a=llabs(a);b=llabs(b);while(b){long long t=a%b;a=b;b=t;}return a;}
static int quadraticExact(char*out,size_t size){if(polyDegree!=2)return 0;double a,b,c;if(!scalar(solverFields[0][0],&a)||!scalar(solverFields[0][1],&b)||!scalar(solverFields[0][2],&c)||a==0)return 0;double d=b*b-4*a*c;if(d<=0||!isfinite(d))return 0;double r=sqrt(d);if(fabs(r-round(r))<1e-12)return 0;
 if(fabs(a-round(a))<1e-12&&fabs(b-round(b))<1e-12&&fabs(c-round(c))<1e-12&&fabs(a)<=10000&&fabs(b)<=10000&&fabs(c)<=10000){long long D=llround(d),factor=1,rest=D;for(long long k=2;k*k<=rest;k++){while(rest%(k*k)==0){rest/=k*k;factor*=k;}}long long n=llround(-b),den=llround(2*a);if(den<0){den=-den;n=-n;}long long g=gcdDisplay(gcdDisplay(n,factor),den);n/=g;factor/=g;den/=g;char radical[100],numerator[160];if(factor==1)snprintf(radical,sizeof(radical),"√%lld",rest);else snprintf(radical,sizeof(radical),"%lld×√%lld",factor,rest);if(n)snprintf(numerator,sizeof(numerator),"%lld ± %s",n,radical);else snprintf(numerator,sizeof(numerator),"± %s",radical);if(den==1)snprintf(out,size,"X = %s",numerator);else snprintf(out,size,"X = (%s)/%lld",numerator,den);return 1;}
 return 0;}
